questions.prompt:
On saisit N avec :
REPEAT
  Write('N : ');
  ReadLn(N);
UNTIL (N >= 2) AND (N <= 40);
L'utilisateur tape successivement 1, 50, 0, 7, puis 12. Quelle est la valeur de N en sortie, et combien de fois le texte N : est-il affiché ?

TYPE Joueur = Record nom : String[10]; points : Integer; End;
PROCEDURE Augmenter (j : Joueur);
BEGIN
  j.points := j.points + 5;
END;
Dans le programme principal, a est de type Joueur et a.points vaut 12.
Augmenter(a);
WriteLn(a.points);
Qu'affiche ce programme ?

TYPE Joueur = Record nom : String[10]; points : Integer; End;
VAR j, k : Joueur;
j.points := 10;
k.points := 3;
With j Do
Begin
  points := points + 1;
  k.points := k.points + points;
End;
Que valent j.points et k.points à la fin ?

N = 4 et T contient (nom, points) : Hedi, 8 ; Mona, 15 ; Ali, 15 ; Rim, 6.
m := 1;
FOR i := 2 TO N DO
  IF T[i].points > T[m].points THEN m := i;
WriteLn(T[m].nom);
Quel nom est affiché ?

N = 5 et T contient (nom, points) : Sana, 12 ; Lina, 9 ; Omar, 14 ; Amel, 11 ; Omar, 7.
i := 1;
WHILE (i <= N) AND (T[i].nom <> 'Omar') DO
  i := i + 1;
WriteLn(i, ' et ', T[i].points);
Qu'affiche ce programme ?
